import heapq


def longestNoTriple(counts):
    h = [(-c, i) for i, c in enumerate(counts) if c > 0]
    heapq.heapify(h)
    length = 0
    last = -1
    run = 0
    while h:
        c, i = heapq.heappop(h)
        if i == last and run == 2:
            if not h:
                break
            c2, i2 = heapq.heappop(h)
            heapq.heappush(h, (c, i))
            c, i = c2, i2
        length += 1
        if i == last:
            run += 1
        else:
            last, run = i, 1
        if c + 1 < 0:
            heapq.heappush(h, (c + 1, i))
    return length
